with metrics as (select *, avg(sqft) over (order by sqft, id rows between 6 preceding and current row) as sqft_avg_6, row_number() over (partition by city order by sqft desc, id) as seq_no, cume_dist() over (partition by city order by sqft desc) as sqft_cume_dist from stores), scored as (select *, sum(sqft_cume_dist) over w_hist as running_sqft_cume_dist, lag(seq_no, 1) over (partition by city order by opened_date, id) as prev_seq_no from metrics window w_hist as (partition by region order by sqft, id rows between unbounded preceding and current row)), enriched as (select *, dense_rank() over (partition by city, region order by sqft_avg_6 nulls first) as sqft_avg_6_dense_rank, avg(prev_seq_no) over (partition by city, region order by sqft_avg_6, id rows between 3 preceding and 1 preceding) as prev_seq_no_avg_3_prior, avg(sqft) over (partition by city) as city_avg_sqft, sum(running_sqft_cume_dist) over (partition by region, city order by opened_date, id rows between unbounded preceding and current row) as running_running_sqft_cume_dist from scored), ranked as (select *, rank() over (partition by city order by sqft desc) as rank_in_group from enriched qualify rank_in_group = 1) select id, store_name, city, region, opened_date, sqft, sqft_avg_6, seq_no, sqft_cume_dist, running_sqft_cume_dist, prev_seq_no, sqft_avg_6_dense_rank, prev_seq_no_avg_3_prior, city_avg_sqft, running_running_sqft_cume_dist, rank_in_group, row_number() over (order by sqft_avg_6 desc, id) as seq_no_2, row_number() over (partition by city order by running_sqft_cume_dist desc, id) as row_seq, ntile(5) over (order by seq_no, id) as seq_no_bucket, count(city_avg_sqft) over (partition by region, city) as region_count_city_avg_sqft from ranked;
